import{_ as n,o as t,c as o,ah as r}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Communication","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/coordinateur/communication.md","filePath":"src/en/guide/coordinateur/communication.md"}'),a={name:"en/guide/coordinateur/communication.md"};function s(i,e,c,g,d,h){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="communication" tabindex="-1">Communication <a class="header-anchor" href="#communication" aria-label="Permalink to &quot;Communication&quot;">​</a></h1><p><strong>Training → Communication</strong> has two sections: <strong>Announcements</strong> and <strong>Deliveries</strong>. The Pedagogical Coordinator and the Administrator have access. Day-to-day exchanges between learners and trainers stay in Sève.</p><h2 id="sending-an-announcement" tabindex="-1">Sending an announcement <a class="header-anchor" href="#sending-an-announcement" aria-label="Permalink to &quot;Sending an announcement&quot;">​</a></h2><p><strong>New announcement</strong>:</p><ol><li>Choose the <strong>recipients</strong>: <strong>A cohort</strong> (current or upcoming) or <strong>A program</strong>, which targets all its current or upcoming cohorts.</li><li>Tick or untick <strong>Include the assigned trainers and coach-tutors</strong>, ticked by default.</li><li>Enter the <strong>subject</strong> and the <strong>message</strong> (separate paragraphs with a blank line).</li><li><strong>Send the announcement</strong>.</li></ol><p>Sending is <strong>immediate</strong>, by e-mail, and on Sève for accounts open there. There is <strong>no WhatsApp</strong> for announcements.</p><p>Recipients are learners whose enrolment is pending signature, active or suspended. Each is served <strong>only once</strong>, even if in several targeted cohorts; an announcement <strong>with no recipient is refused</strong>.</p><p>The <strong>Announcements sent</strong> list keeps, for each, its author, number of recipients, e-mails, Sève deliveries and failures.</p><h2 id="the-deliveries-log" tabindex="-1">The deliveries log <a class="header-anchor" href="#the-deliveries-log" aria-label="Permalink to &quot;The deliveries log&quot;">​</a></h2><p><strong>Deliveries</strong> shows <strong>everything the notification engine has sent</strong>: reminders, notices and announcements, channel by channel, with the recipient, message, date, status (<strong>Sent</strong> or <strong>Failed</strong>) and any error.</p><p>Filter by channel and status, search for a recipient or subject, and use <strong>Show failures</strong> to find what did not get through, with the number of failures over the last 30 days. A failing channel does not stop the others: a message that could not go out on Sève went out by e-mail.</p>',11)])])}const m=n(a,[["render",s]]);export{u as __pageData,m as default};
